referenceSolutions.javascript:
export function cheapestFlightsWithinKStops(n        , flights            , source        , destination        , k        )         {
let costs=Array(n).fill(Infinity);costs[source]=0;for(let step=0;step<=k;step++){const next=[...costs];for(const [a,b,p]of flights)next[b]=Math.min(next[b],costs[a]+p);costs=next;}return costs[destination]===Infinity?-1:costs[destination];
}

